            return 0
        adj_matrix = [[0] * n for _ in range(n)]
        for i, neighbors in enumerate(G):
            for j in neighbors:
                adj_matrix[i][j] = 1
                adj_matrix[j][i] = 1

        # Gaussian elimination to find the rank of the adjacency matrix
        rank = 0
        for i in range(n):
