                        found_nonzero_row = True
                        break
                if not found_nonzero_row:
                    continue

            rank += 1
            denom = adj_matrix[i][i]
            for j in range(n):
                adj_matrix[i][j] /= denom

            for j in range(n):
                if i != j:
                    factor = adj_matrix[j][i]
                    for k in range(n):
